export function slugify(value: string, options: SlugOptions = {}): string {
	// Normalize diacritics (e.g. é → e, û → u)
	const normalized = value.normalize("NFD").replace(/[\u0300-\u036f]/g, "");

	// Replace any non-alphanumeric, non-space character with a space
	let slug = normalized.replace(/[^\w\s-]/g, " ");

	// Collapse runs of whitespace / hyphens into a single hyphen
	slug = slug.replace(/[\s-]+/g, "-");

	// Trim leading/trailing hyphens
	slug = slug.replace(/^-|-$/g, "");

	// Apply maxLength: truncate at the nearest word boundary
	if (options.maxLength != null && options.maxLength > 0) {
		if (slug.length > options.maxLength) {
			slug = slug.slice(0, options.maxLength);
			// Remove trailing hyphen (truncate at word boundary)
			slug = slug.replace(/-+$/g, "");
		}
	}

	return slug;
}

